import{_ as l,c as e,o as i,ae as t}from"./chunks/framework.DNEoaTf_.js";const b=JSON.parse('{"title":"更新履歴","description":"","frontmatter":{},"headers":[],"relativePath":"ja/changelog.md","filePath":"ja/changelog.md"}'),r={name:"ja/changelog.md"};function o(h,a,u,s,n,c){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="更新履歴" tabindex="-1">更新履歴 <a class="header-anchor" href="#更新履歴" aria-label="Permalink to &quot;更新履歴&quot;">​</a></h1><p>このページでは、YouTube Watch Thumbnails の変更履歴を記載しています。</p><p>詳細な変更ログは、<a href="https://github.com/mosunset/youtube_watch_thumbnails/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">GitHub の CHANGELOG.md</a> をご覧ください。</p><h2 id="v1-0-0-2024-11-24" tabindex="-1">v1.0.0 (2024-11-24) <a class="header-anchor" href="#v1-0-0-2024-11-24" aria-label="Permalink to &quot;v1.0.0 (2024-11-24)&quot;">​</a></h2><h3 id="✨-新機能" tabindex="-1">✨ 新機能 <a class="header-anchor" href="#✨-新機能" aria-label="Permalink to &quot;✨ 新機能&quot;">​</a></h3><ul><li>ツールバーアイコンからワンクリックでサムネイル表示</li><li>YouTube 視聴ページへのサムネイル直接表示</li><li>Thumbnail View で全解像度・全フォーマットを一覧表示</li><li>最大画質 (maxresdefault) から低画質まで対応</li><li>JPG / WebP 両フォーマットに対応</li><li>YouTube Shorts のサムネイル取得に対応</li></ul><h3 id="🎨-ui-ux" tabindex="-1">🎨 UI/UX <a class="header-anchor" href="#🎨-ui-ux" aria-label="Permalink to &quot;🎨 UI/UX&quot;">​</a></h3><ul><li>シンプルで直感的なポップアップデザイン</li><li>高速なサムネイル表示</li><li>ワンクリックでダウンロード可能</li></ul><h3 id="🔒-プライバシー" tabindex="-1">🔒 プライバシー <a class="header-anchor" href="#🔒-プライバシー" aria-label="Permalink to &quot;🔒 プライバシー&quot;">​</a></h3><ul><li>データを一切保存しない設計</li><li>リアルタイム処理のみ</li><li>オープンソースでコードを公開</li></ul><h3 id="🌐-対応ブラウザ" tabindex="-1">🌐 対応ブラウザ <a class="header-anchor" href="#🌐-対応ブラウザ" aria-label="Permalink to &quot;🌐 対応ブラウザ&quot;">​</a></h3><ul><li>Google Chrome</li><li>Microsoft Edge</li><li>Brave</li><li>その他 Chromium ベースのブラウザ</li><li>Firefox（予定）</li></ul><hr><h2 id="ロードマップ" tabindex="-1">ロードマップ <a class="header-anchor" href="#ロードマップ" aria-label="Permalink to &quot;ロードマップ&quot;">​</a></h2><p>今後の予定機能：</p><ul><li>[ ] Firefox への正式対応</li><li>[ ] サムネイルの一括ダウンロード機能</li><li>[ ] カスタムサムネイルサイズの指定</li><li>[ ] サムネイルのプレビュー機能強化</li></ul><hr><div class="tip custom-block"><p class="custom-block-title">フィードバック</p><p>機能リクエストやバグ報告は、<a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">GitHub Issues</a> でお気軽にお寄せください。</p></div>',18)])])}const m=l(r,[["render",o]]);export{b as __pageData,m as default};
